const verifyFiles = async (key, files) => {
  if (!ref) return; const r = ref[key]; if (!r) { (T.verify.noref ||= []).push(key); return; }   // R9：无 Python 参照的单元（C512 控制器、K6 / 选择器 / 胶合）另列
  for (const [n, a] of Object.entries(files)) { const h = await hex(bytesOf(a)); T.verify.files++; if (r && r[n + '.u32'] === h) T.verify.same++; else T.verify.diff.push(`${key}/${n}`); }
};

const loadFrom = async (files, meta, extraHooks, tag) => {
  const vfs = new Map(Object.entries(files).map(([n, a]) => [`x/${n}.u32`, bytesOf(a)])); vfs.set('x/ir-meta.json', enc.encode(JSON.stringify(meta)));
  const rd = async p => { const v = vfs.get(p); if (v) return v; const m = p.match(/^cells\/([^/]+)\.bin$/); if (m && cellBins.has(m[1])) return cellBins.get(m[1]); throw new Error('missing ' + p); };
  let L; try { L = await loadLayer(g, rd, 'x', execMan, 'cells', s => log(`[${tag}] ${s}`), { ...hooks, ...extraHooks }); } catch (e) { console.error(`LOADFAIL ${tag}`, e && e.stack, JSON.stringify({ files: Object.fromEntries(Object.entries(files).map(([k, v]) => [k, v && v.length])) })); throw e; }
  vfs.clear(); return L;
};
